    return [dtype(x) for x in input().split()]

def ceil1(a, b):
    return (a + b - 1) // b

def add(a, b):
    return (a + b) % mod

def mult(a, b):
    return (a * b) % mod

n, mod = inp(int)
mem, su = [0, 1], 1

for i in range(2, n + 1):
    sq, cur = int(i ** .5) + 1, su

    for f in range(2, sq):
        cur = add(cur, mem[i // f])

    be = i
    for j in range(1, i // sq + 1):
        nxt = i // (j + 1)
        cur = add(cur, mult(be - nxt, mem[j]))
        be = nxt

    su = add(su, cur)
    mem.append(cur)
print(mem[-1])

